import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第四十四卦 姤 天风姤 乾上巽下","description":"周易 - 第四十四卦 姤 天风姤 乾上巽下","frontmatter":{"title":"第四十四卦 姤 天风姤 乾上巽下","description":"周易 - 第四十四卦 姤 天风姤 乾上巽下"},"headers":[],"relativePath":"zh/classics/zhouyi/045.md","filePath":"zh/classics/zhouyi/045.md"}'),l={name:"zh/classics/zhouyi/045.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="姤" tabindex="-1">姤 <a class="header-anchor" href="#姤" aria-label="Permalink to “姤”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>女壮，勿用取女。</p><h3 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to “彖传”">​</a></h3><p>姤，遇也，柔遇刚也。勿用取女，不可与长也。天地相遇，品物咸章也。刚遇中正，天下大行也。姤之时义大矣哉！</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>天下有风，姤；后以施命诰四方。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>系于金柅，贞吉，有攸往，见凶， 羸豕踟躅。象曰：系于金柅，柔道牵也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>包有鱼，无咎，不利宾。象曰：包有鱼，义不及宾也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>臀无肤，其行次且，厉，无大咎。象曰：其行次且，行未牵也。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>包无鱼，起凶。象曰：无鱼之凶，远民也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>以杞包瓜，含章，有陨自天。象曰：九五含章，中正也。有陨自天，志不舍命也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>姤其角，吝，无咎。象曰：姤其角，上穷吝也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
